import{_ as e,c as a,o as s,a3 as n}from"./chunks/framework.Dokpd4od.js";const g=JSON.parse('{"title":"Acquire leads","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/crm/acquire-leads/index.md","filePath":"master/sales/crm/acquire-leads/index.md","lastUpdated":1793789158000}'),o={name:"master/sales/crm/acquire-leads/index.md"};function r(d,t,i,l,h,p){return s(),a("div",null,t[0]||(t[0]=[n(`<h1 id="acquire-leads" tabindex="-1">Acquire leads <a class="header-anchor" href="#acquire-leads" aria-label="Permalink to &quot;Acquire leads&quot;">​</a></h1><p>This group covers how a possible customer enters CRM and becomes an opportunity. You can create a lead by hand, or let rules create leads from website visitors. When a lead looks serious, you convert it to an opportunity and start working it in the pipeline.</p><blockquote><p><strong>In simple words:</strong> First you collect names. Then you pick the good ones and work on them.</p></blockquote><p>Leads are optional. Switch on <strong>Lead Qualification</strong> in <code>CRM → Settings → Manage CRM</code> to get the <strong>Leads</strong> area. See <a href="./../configuration/settings.html">CRM settings</a>.</p><h2 id="the-flow" tabindex="-1">The flow <a class="header-anchor" href="#the-flow" aria-label="Permalink to &quot;The flow&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Source of enquiry                 Lead                    Opportunity</span></span>
<span class="line"><span>-----------------      +---------------------+      +------------------+</span></span>
<span class="line"><span>You type it in   ----&gt; |  Check details,     | ---&gt; | Appears in My    |</span></span>
<span class="line"><span>Website visitor  ----&gt; |  priority, tags,    |      | Pipeline in the  |</span></span>
<span class="line"><span>matches a rule   ----&gt; |  probability        |      | first stage      |</span></span>
<span class="line"><span>                       +---------------------+      +------------------+</span></span>
<span class="line"><span>                                  |</span></span>
<span class="line"><span>                                  +--&gt; Lost (reason + note) --&gt; Lost view</span></span>
<span class="line"><span>                                  +--&gt; Merge with similar records</span></span></code></pre></div><ol><li><strong>Collect.</strong> Create a lead yourself, or turn on visitor rules. See <a href="./create-lead.html">Create a lead</a> and <a href="./lead-generation.html">Generate leads from visitors</a>.</li><li><strong>Check.</strong> Review the contact details, priority and tags. Open the <strong>Similar Leads</strong> tab to find duplicates.</li><li><strong>Convert.</strong> Click <strong>Convert to Opportunity</strong>. See <a href="./convert-lead.html">Convert a lead</a>.</li><li><strong>Work.</strong> Continue in the <a href="./../pipeline/">Pipeline</a>.</li></ol><h2 id="states-of-a-lead" tabindex="-1">States of a lead <a class="header-anchor" href="#states-of-a-lead" aria-label="Permalink to &quot;States of a lead&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Meaning</th><th>How it changes</th></tr></thead><tbody><tr><td><strong>Open</strong></td><td>A lead you still need to check. It shows in <strong>My Leads</strong>, <strong>Unassigned</strong> and <strong>All Leads</strong>.</td><td><strong>Convert to Opportunity</strong> or <strong>Lost</strong></td></tr><tr><td><strong>Lost</strong></td><td>You closed it, or deleted it. It shows in the <strong>Lost</strong> view with the reason.</td><td><strong>Restore</strong></td></tr><tr><td><strong>Opportunity</strong></td><td>The lead was converted. It leaves the <strong>Leads</strong> list and joins the pipeline.</td><td>See <a href="./../pipeline/">Pipeline</a></td></tr></tbody></table><h2 id="buttons-on-a-lead" tabindex="-1">Buttons on a lead <a class="header-anchor" href="#buttons-on-a-lead" aria-label="Permalink to &quot;Buttons on a lead&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Button</th><th>Open lead</th><th>Lost lead</th></tr></thead><tbody><tr><td><strong>Convert to Opportunity</strong></td><td>Yes</td><td>-</td></tr><tr><td><strong>Lost</strong></td><td>Yes</td><td>-</td></tr><tr><td><strong>Send email</strong></td><td>Yes, if the lead has an email</td><td>-</td></tr><tr><td><strong>Send SMS</strong></td><td>Yes</td><td>-</td></tr><tr><td><strong>Delete</strong></td><td>Yes</td><td>-</td></tr><tr><td><strong>Restore</strong></td><td>-</td><td>Yes</td></tr></tbody></table><h2 id="pages-in-this-group" tabindex="-1">Pages in this group <a class="header-anchor" href="#pages-in-this-group" aria-label="Permalink to &quot;Pages in this group&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>What it helps you do</th></tr></thead><tbody><tr><td><a href="./create-lead.html">Create a lead</a></td><td>Use the leads list and record a new enquiry with contact, sales and marketing details.</td></tr><tr><td><a href="./convert-lead.html">Convert a lead</a></td><td>Turn leads into opportunities, merge duplicates and choose the customer.</td></tr><tr><td><a href="./lead-generation.html">Generate leads from visitors</a></td><td>Create leads from website visits with rules.</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../">CRM overview</a></li><li><a href="./../assign-and-track/lead-scoring.html">Lead scoring</a></li><li><a href="./../../../getting-started/contacts/contacts.html">Contacts</a></li></ul>`,15)]))}const u=e(o,[["render",r]]);export{g as __pageData,u as default};
